    # Extend the marked diagonal pattern by copies of the same shape.
    # The shape's bounding-box size gives the repeat interval.
    rmin, rmax = min(r for r, c in pts), max(r for r, c in pts)
    cmin, cmax = min(c for r, c in pts), max(c for r, c in pts)
    dh, dw = rmax - rmin + 1, cmax - cmin + 1

    for dr, dc in ((-dh, -dw), (dh, dw)):
        k = 1
        while True:
            shifted = [(r + k * dr, c + k * dc) for r, c in pts]
            if not all(0 <= r < h and 0 <= c < w for r, c in shifted):
                break
            for r, c in shifted:
                out[r][c] = color
            k += 1
    return out
