def transform(grid):
    h, w = len(grid), len(grid[0])
    color = next((v for row in grid for v in row if v not in (0, 1)), None)
    if color is None:
        return [row[:] for row in grid]

    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    out = [row[:] for row in grid]
    r0, r1 = min(r for r, c in points), max(r for r, c in points)
    c0, c1 = min(c for r, c in points), max(c for r, c in points)
    sh, sw = r1 - r0 + 1, c1 - c0 + 1

    # Copy the colored motif in a lattice using its bounding-box dimensions.
    for a in range(-h, h + 1):
        for b in range(-w, w + 1):
            if a == 0 and b == 0:
                continue
            dr, dc = a * sh, b * sw
            shifted = [(r + dr, c + dc) for r, c in points]
            for r, c in shifted:
                if 0 <= r < h and 0 <= c < w and grid[r][c] == 0:
                    out[r][c] = color
    return out
